"""Author-maintained learning notes. Examples are original, not official answers."""
import json,pathlib,sys,re,xml.etree.ElementTree as ET
OUT=pathlib.Path(__file__).resolve().parents[1]/'assets/ronbun'
LAW={'const':('憲法','321CONSTITUTION'),'civil':('民法','129AC0000000089'),'crime':('刑法','140AC0000000045'),'civpro':('民事訴訟法','408AC0000000109'),'crimpro':('刑事訴訟法','323AC0000000131'),'company':('会社法','417AC0000000086'),'admin':('行政事件訴訟法','337AC0000000139'),'procedure':('行政手続法','405AC0000000088'),'state':('国家賠償法','322AC0000000125'),'execution':('民事執行法','354AC0000000004'),'preserve':('民事保全法','401AC0000000091'),'lawyer':('弁護士法','324AC1000000205')}
lessons=[]
def L(subject,id,title,rule,steps,pitfall,example,question,answer,keywords,refs='',minutes=18):
 sources=[]
 for spec in refs.split(';'):
  if not spec:continue
  key,arts=spec.split(':');name,lawid=LAW[key.strip()];sources.append({'name':name,'lawId':lawid,'articles':arts.strip().split(','),'url':'https://laws.e-gov.go.jp/law/'+lawid})
 lessons.append(dict(id=id,subject=subject,title=title,rule=rule,steps=steps.split('｜'),pitfall=pitfall,example=example,recall=[{'question':question,'answer':answer}],keywords=keywords.split('｜'),sources=sources,minutes=minutes))

L('答案の基本','write-01','設問から答案の骨格を作る','論文で最初に決めるのは、誰のどの請求・主張・罪責を論じるかである。設問の限定、立場の指定、検討不要事項は答案の外枠になる。知っている論点の列挙から入ると、結論のない答案や問われていない論点の長い説明になりやすい。','設問の動詞を囲む。「請求できるか」「適法か」「反論せよ」の違いを確認する。｜主体・相手方・法律効果を一行で書き、設問ごとに見出しを置く。｜必要な条文と要件を並べ、争われる要件に事実を割り振る。｜最後の結論を仮置きし、反対事情で修正する。','問題文を読み終わってから設問を初めて見る。設問ごとの結論を書かず、議論の途中で終わる。','「XはYに土地明渡しを請求できるか」なら、まず所有権に基づく返還請求を特定する。Xの所有、Yの占有、Yの占有権原という順に検討し、売買契約の話を直ちに損害賠償へ飛ばさない。','論点名を見つけた後、最初に何を特定するか。','その論点を解決して認めたい法律効果と、その効果を求める主体・相手方。','設問｜請求｜罪責',minutes=15)
L('答案の基本','write-02','規範と当てはめを分ける','規範は事実を評価する物差し、当てはめは個別事情がその物差しを満たす理由である。条文をそのまま適用できる点と、文言の解釈・判例の規範が必要な点を分ける。規範は暗唱だけでなく、なぜその基準を用いるかを短く説明できるようにする。','根拠条文と法律効果を示す。｜問題となる文言の意味を、趣旨・対立利益から説明する。｜規範を要素に分け、各要素に有利・不利な事実を対応させる。｜事実の引用の後に「このため、○○と評価できる」と意味付けする。','「本件では要件を満たす」で当てはめを終える。事実を大量に転記するだけで評価しない。','「夜間、逃走経路がふさがれ、相手が刃物を構えた」という事実を挙げるだけでは足りない。「回避の余地が乏しく身体への危険が切迫していた」と評価し、防衛行為の必要性の判断につなげる。','「事実の摘示」と「評価」はどう違うか。','摘示は問題文の事情を示すこと。評価は、その事情が規範のどの要素をどの方向に支えるかを説明すること。','規範｜事実｜評価',minutes=18)
L('答案の基本','write-03','反対事情と判例の射程','有力な反対事情を落とした答案は、結論が正しくても説得力を失う。判例を使う際は、結論だけでなく重要な事実・規制の仕組み・問題となった利益を比較する。類似事案というだけで結論を移すのではなく、共通点と相違点が規範の適用に与える影響を書く。','自分の結論に最も不利な事実を一つ選ぶ。｜その事実が支える反論を、相手に有利な形で整理する。｜判例の重要な事実と本件の共通点・相違点を挙げる。｜違いを踏まえて規範を適用し、反論への応答を示す。','判例名を挙げれば点が入ると考える。反対説を「妥当でない」とだけ処理する。','有害図書規制の判例を政治的表現の規制に使うなら、青少年保護という目的の共通性と、規制される表現の価値・対象範囲の違いを分ける。「前例が合憲だから本件も合憲」としない。','判例の射程を検討するとき、比較すべきものは。','結論を支えた重要な事実と制度の構造、保護利益、規制の強度。単に当事者名や場所を比較するのではない。','判例｜反対｜利益',minutes=18)
L('答案の基本','write-04','70分の起案とCBTの文字配分','基本科目は科目群ごとに一括した試験時間で実施される。単科目70分は学習上の等分目安であり、各科目に独立した本番の締切があるわけではない。令和8年の公式方式では各科目4頁、1頁23行、1行最大30文字。改行や見出しも頁を使うため、文字数だけでなく答案の行数も意識する。','練習では読解10分・構成15分・起案40分・確認5分から始め、自分の記録で調整する。｜設問の配点比が明示されていれば、時間と紙幅を優先して配分する。｜大きな争点に長く、小さな争点には短く書く。見出しは結論に至る階層を示す。｜科目群の練習では、苦手科目に時間を使い切って他科目を白紙にしない。','2760文字を埋めることを目的にする。入力欄の取り違えや氏名などの記載を見落とす。','2設問の比重が2対1なら、構成段階で主要争点と文字配分を決める。前半の定義に1000字を費やし、後半の当てはめが一行になる状態を、答案を書く前に防ぐ。','このサイトの頁数は本番CBTと完全に同じか。','30文字・23行を基準にした練習の目安。実際の入力・改行・表示は公式CBTの案内と体験環境で確認する。','時間｜配点｜答案',minutes=15)
L('答案の基本','write-05','出題趣旨から復習課題を作る','公式出題趣旨は、設問が求める検討内容と問題意識を示す資料であり、唯一の完成答案ではない。照合では「同じ言葉があるか」ではなく、主要争点・規範・重要事実・結論への筋道が答案に現れているかを見る。自己点検の項目数を本試験の点数や合格率に換算しない。','答案を書き終えて保存してから出題趣旨を開く。｜趣旨の要求を短い確認項目に直す。答案の対応箇所を引用して根拠を残す。｜知識不足・争点落ち・事実評価不足・時間不足に原因を分ける。｜一番大きい不足を直した答案を別欄に書き、日を空けて資料を見ずに再現する。','解説を読んで理解した感覚だけで復習を終える。原答案を上書きして、どこが改善したか分からなくする。','「原告適格の判断で関係法令の目的を分析する」という趣旨に対し、答案が9条の定義しかないなら、条文暗記の不足ではなく、根拠法令を具体的に読む作業が不足していると記録する。','出題趣旨を読んだ直後に書けたことだけで定着と考えてよいか。','直後は記憶の助けが大きい。別の日に資料を閉じて構成と主要な当てはめを再現し、定着を確認する。','出題趣旨｜検討｜理由',minutes=15)
L('答案の基本','write-06','基礎・構成・起案を週ごとに回す','知識の暗記だけでも、知らないまま大量に起案するだけでも改善しにくい。講義で要件と典型事実を確認し、15〜25分の答案構成、時間を測った全文起案、書き直しを循環させる。学習時間は目安であり、同じ時間を使えば合格するという意味ではない。','初期は条文・基本構造と短い答案例を読み、見ないで説明する。｜構成練習では全設問の結論と当てはめの事実を箇条書きにする。｜毎週の起案を最低限確保し、科目を偏らせず9分野を回す。｜直前期は未着手の新教材を増やすより、過去答案の重大な不足と本番時間での完答を優先する。','得意科目の講義だけを繰り返す。実務基礎と倫理の学習を最後まで後回しにする。','週12時間の配分例は、基礎4時間、構成3時間、起案3時間、復習2時間。残業などで時間が少ない週も、前回の答案の一段落を書き直す作業を残す。','自分の学習配分を変える判断材料は。','起案の記録。規範が出ないなら基礎、争点が抜けるなら構成、時間内に書き切れないなら時間を測った起案を厚くする。','法律実務基礎｜答案｜理解',minutes=12)

L('憲法','const-01','人権答案の入口：権利・制約・正当化','憲法上の権利を主張する主体と、国家のどの行為がどの活動を妨げるかを具体化する。保障範囲、制約、制約の正当化を順に検討する。審査基準の名称を先に置かず、権利の性質、規制の目的・態様・強度から司法審査の密度を説明する。','行為を具体的に書き、対応する条文を挙げる。｜権利の保障根拠と主体性を確認する。｜禁止・許可制・不利益・萎縮など制約の内容を特定する。｜目的と手段を切り分け、必要性・過大な制約・代替手段を論じる。','全ての人権を同じ審査基準で処理する。国側の目的を抽象的な「公益」で済ませる。','公園でのビラ配布を一律禁止する条例では、表現活動の内容、場所の管理目的、通行妨害の実態を分ける。混雑する時間帯だけの制限で足りるかは、手段の過剰性を検討する材料になる。','審査の厳格さを決める要素は。','権利の重要性だけでなく、内容に着目する規制か、直接か付随的か、制約の強度、制度の性質、判断の専門性など。','表現｜制約｜目的','const:13,21,22,29')
L('憲法','const-02','私人間効力・外国人・法人・公務員','憲法の人権規定は原則として国家と個人の関係を規律する。私人間の紛争では民法の一般条項等の解釈を通じて人権の趣旨を考慮する。外国人や法人には権利の性質に応じた保障を検討し、公務員も人権主体であることと職務上の制約の正当化を区別する。','争う相手が国家か私人かを判別する。｜主体の性質上、当該権利が保障されるかを検討する。｜私人間なら契約自由・団体の自治と、個人の利益を調整する私法上の構成を置く。｜公務員の制約は職務内容・地位・行為の態様に即して検討する。','私人の行為に憲法を直ちに直接適用する。法人だから人権はない、公務員だから全面禁止できるとする。','会社が従業員の思想を理由に不利益を与えた場合、国家による思想統制と同じ構成を機械的に用いず、私法上の有効性を判断する場面で思想・良心の自由の趣旨と契約関係を考慮する。','外国人の人権で「性質上日本国民のみ」と考える作業は何か。','その権利の目的・内容と国籍の関係を個別に検討すること。外国人一般について一括して保障を否定することではない。','外国人｜法人｜公務員｜私人','const:13,19,21; civil:90')
L('憲法','const-03','平等原則：区別の理由を検討する','平等は、異なる取扱いを全て禁止するものではない。誰と誰の間に、どの基準による、どの利益の差があるかを特定し、区別の目的と手段の合理性を審査する。区別の対象や不利益の重さによって、合理性をどの程度厳しく検討すべきかが変わる。','比較する二つの集団と取扱いの差を明示する。｜区別の基準が本人の意思・努力で変えにくいものか確認する。｜制度目的に照らし区別が意味を持つか、対象が過不足なく設定されているかを検討する。｜結論と、不合理と考える部分を具体化する。','14条後段の列挙だけを理由に当然違憲とする。異なる取扱いの具体的な内容を示さない。','給付制度で一定年齢以上を一律排除するなら、制度目的が就業支援なのか生活保障なのかで、年齢が目的達成に結びつく程度は変わる。目的を確認せず「年齢差別だから違憲」としない。','平等答案で、目的・手段に入る前に書くべきことは。','比較集団、区別基準、具体的な利益・負担の差。','平等｜区別｜合理','const:14')
L('憲法','const-04','表現の自由：内容規制と場所・方法の規制','表現の自由は自己実現と民主的意思形成を支える。内容に着目する規制では、特定の思想を排除する危険や萎縮を重視する。場所・方法の規制でも、表現の機会が実質的に失われるか、代替経路があるかを具体的に検討する。','規制の対象が思想内容か、騒音・通行等の外形かを読み分ける。｜表現の種類と、受け手の情報摂取の利益を確認する。｜危険の具体性、規制の範囲、許可基準の明確さを検討する。｜より制限的でない手段が現実に機能するかを考える。','内容中立なら必ず合憲とする。表現規制を経済的利益の制限としてだけ扱う。','拡声器の深夜使用制限なら、騒音防止の必要性と、時間・音量の限定を検討する。特定の政治主張にだけ適用される運用があれば、形式上の文言だけで内容中立と決めない。','規制目的が正当なら、手段の検討は不要か。','不要ではない。対象、期間、例外、代替手段、萎縮の程度まで検討する。','表現｜ビラ｜情報｜集会','const:21')
L('憲法','const-05','検閲・事前抑制・明確性・広範性','検閲は判例上の要件に沿って限定的に判断される。検閲に当たらなくても事前抑制の問題は残る。また、禁止範囲が理解できず萎縮を招く不明確な規制と、本来保護される表現まで大量に取り込む広範な規制は別の観点である。','主体、対象、発表前の審査、網羅性、発表禁止の仕組みを確認する。｜検閲該当性と、その他の事前抑制としての許容性を分ける。｜一般人が規制対象を判断できるかを検討する。｜保護される表現への波及、個別判断・不服申立て等の手続を検討する。','「検閲に当たらない」で合憲と結論する。不明確性と広範性を同じ問題とする。','発売後に適用される規制でも、事実上次号の発行を止める構造なら事前抑制の問題を検討する。禁止語が明確に列挙されていても、批判目的の引用まで禁止するなら広範性の問題が残る。','明確に定義された規制にも広範性の問題は生じるか。','生じる。何が禁止されるか明確でも、必要な範囲を超えて保護される表現を含み得る。','検閲｜事前抑制｜明確｜広範','const:21')
L('憲法','const-06','思想・良心、信教の自由と政教分離','内心の自由、外部に現れる行為の自由、国家と宗教の関係を区別する。宗教的動機があっても外部行為は他者の利益と衝突し得る。他方、国家の宗教的活動は、個人の信仰を強制していなくても政教分離の問題となる。','内心そのものへの介入か、行為への命令・禁止かを特定する。｜信仰を理由に受ける不利益の具体的内容を確認する。｜国家の関与では施設・金銭・行事・目的・社会的文脈を把握する。｜目的・効果など判例の判断枠組みを、事案の性質に即して用いる。','宗教に関係する国の行為は全て違憲とする。形式的な名称だけで世俗的行事と決める。','自治体が宗教施設へ無償で土地を提供する事例では、提供の経緯、規模、継続性、他宗教との関係、社会一般から見た援助の程度を検討する。信仰強制がないという一点で終えない。','信教の自由と政教分離の検討は同じか。','前者は個人の自由、後者は国家と宗教の関係を主に問題とし、同じ事例でも別々の観点から検討する。','宗教｜信教｜思想｜政教','const:19,20,89')
L('憲法','const-07','職業の自由・財産権・損失補償','職業活動への規制では、参入自体を止めるものか営業方法を限定するものかを区別する。財産権は公共の福祉に適合するよう法律で内容を定められるが、目的だけで制約が正当化されるわけではない。適法な公権力行使でも特別の犠牲が生じれば補償の検討が必要となる。','職業選択・遂行のどちらに、どの強度の負担があるかを書く。｜規制目的と制度の性質を読み、立法裁量と手段の合理性を検討する。｜財産の性質、従前の利用、規制の程度と一般性を検討する。｜国家賠償と損失補償を区別し、特別の犠牲と正当な補償を論じる。','経済的自由だから緩やかな審査でよいとだけ書く。補償があるからどのような収用も適法とする。','資格制度で一定距離以内の新規開業を禁止する場合、質の確保という目的に距離がどう結びつくかを検討する。店舗設備の検査など、目的に直接対応する別手段にも触れる。','損害賠償と損失補償の基本的な違いは。','前者は違法な権利侵害などを、後者は適法な公権力行使による特別の犠牲を主に扱う。','職業｜財産｜補償｜営業','const:22,29')
L('憲法','const-08','プライバシー・自己決定・適正手続','憲法13条の保障を論じるときは、新しい権利名を置くだけでなく、具体的利益が人格的生存にどう関わるかを示す。情報の取得・保存・利用・提供は別の侵害局面である。手続保障は不利益の性質・重大性、公益、事前手続の必要性を具体的に考える。','秘匿したい情報や自己決定の対象を特定する。｜取得方法、保存期間、利用目的、第三者提供の範囲を分ける。｜必要性と危険防止の仕組み、代替手段を検討する。｜告知・聴聞・理由提示・不服申立ての有無を確認する。','抽象的な「プライバシー侵害」で終える。本人が一度公開した情報は以後一切保護されないとする。','位置情報の継続収集では、一回の現在地の確認と、生活全体を推知できる長期の蓄積を区別する。目的を限定した収集、保存期間、アクセス管理が侵害の程度に関係する。','情報収集が適法なら、別目的の提供も当然に適法か。','別の利用・提供による侵害を改めて検討する必要がある。','プライバシー｜個人情報｜手続｜自己決定','const:13,31,35')
L('憲法','const-09','社会権・教育・参政権','生存権や教育に関する制度では、法律による具体化と裁量の統制を意識する。国会に裁量があることは無審査を意味しない。選挙権等の参政権では、民主制の基礎となる性格を踏まえ、権利行使を制限する具体的理由と必要性を検討する。','権利の保障内容と請求している救済を区別する。｜制度目的、専門的判断、財政的要素を把握する。｜著しい不合理や重要事項の考慮漏れがないか、事実に即して検討する。｜選挙権の制限では対象、期間、例外、実施可能な代替手段を確認する。','生存権はプログラムだから裁判で問題にならないと即断する。給付請求と差別的取扱いの是正を混同する。','給付額の変更を争うなら、生活実態や計算方法を踏まえる。選挙の投票方法の制限を争うなら、本人の状況と代替制度の実現可能性を具体的に検討する。','裁量が認められる分野では、何を書けばよいか。','裁量の根拠と限界を示し、判断過程・重要な事実・目的との関係に即して逸脱や不合理を検討する。','生存｜教育｜選挙｜投票','const:15,25,26,44')
L('憲法','const-10','統治・司法権・法律上の争訟','裁判所の具体的争訟の審判と、抽象的な憲法判断を区別する。法律上の争訟は当事者間の具体的な権利義務・法律関係をめぐり、法令の適用により終局的に解決できる紛争である。議院の自律や行政の判断に関わる場合も、司法審査の限界を問題に即して論じる。','求める判決と、その前提となる具体的な権利義務を示す。｜法令適用により解決できる争いかを検討する。｜国会・内閣・地方自治・裁判所の権限配分を条文から確認する。｜付随的違憲審査、裁量、統治行為等の議論を必要な範囲で用いる。','憲法違反を主張すれば抽象的に訴えられるとする。政治性があるだけで司法審査を全面否定する。','宗教団体の内部紛争でも、寄附金返還など具体的な私法上の請求なら法律上の争訟になり得る。ただし、解決に宗教上の教義判断が不可欠かを別途検討する。','違憲審査はどのような紛争で行われるのが原則か。','具体的な法律上の争訟を解決するのに必要な範囲で、適用法令等の憲法適合性を審査する。','司法権｜争訟｜国会｜地方自治','const:41,65,76,81,92,94')

L('行政法','admin-01','取消訴訟の入口と処分性','行政行為の名称にとらわれず、国民の権利義務・法的地位に直接の法的影響を与える公権力の行為かを検討する。勧告や計画も制度全体の中で実質的にどう作用するかを読む。処分性、原告適格、訴えの利益、出訴期間は別々の訴訟要件である。','誰がどの行為の取消しを求めるかを特定する。｜根拠法の仕組みと後続手続を図式化する。｜法的効果の直接性と、今争う必要性を判例の枠組みに沿って検討する。｜被告、管轄、期間、他の訴訟要件も設問に応じて整理する。','処分という名称がないから処分性を否定する。事実上の不利益があれば必ず処分性があるとする。','行政庁の勧告に従わないと後続の不利益処分が事実上避けられない制度では、勧告の形式だけでなく根拠法と運用上の結び付き、救済の実効性を検討する。','処分性と原告適格の違いは。','処分性は争う行政行為の性質、原告適格はその行為を誰が争えるかの問題。','処分性｜勧告｜計画｜取消','admin:3,9,11,14')
L('行政法','admin-02','原告適格：根拠法令を読み切る','取消訴訟の原告適格は、処分の取消しを求める法律上の利益があるかによる。処分の相手方以外では、根拠法令と関係法令が、個々人の具体的利益を一般的公益に吸収せず保護しているかを読む。行政事件訴訟法9条2項の考慮事項を具体的な条文に結び付ける。','原告の利益を生命・身体・生活・営業等に特定する。｜根拠法の目的、規制要件、関連法令を拾う。｜利益の内容・性質と、侵害の態様・程度を分析する。｜その保護が及ぶ地理的・人的範囲に原告が入るかを論じる。','9条2項を丸写しし、資料の条文を検討しない。住民だから当然に原告適格があるとする。','危険施設の周辺住民なら、距離だけでなく事故時の被害の範囲、法が防ごうとする危険の性質を検討する。競業者の売上減少は、根拠法が競業上の利益まで保護するかを吟味する。','原告適格の当てはめで最も重要な資料は。','問題文の根拠法令・関係法令と、原告が受ける具体的な利益侵害の事情。','原告適格｜法律上の利益｜住民｜競業','admin:9,10')
L('行政法','admin-03','訴えの利益・出訴期間・無効確認','処分後の事情変更で効果が消えても、取消しによって回復すべき法律上の利益が残るかを検討する。期間経過、施設完成、後続処分などを区別する。無効確認は取消訴訟の期間制限を自由に回避する制度ではなく、無効を基礎づける瑕疵と確認の利益が問題となる。','訴訟の現在時点で処分の効果が何を残しているか整理する。｜取消しで除去できる法的な不利益かを確認する。｜出訴期間の主観的・客観的起算点と正当な理由を確認する。｜重大・明白な瑕疵等の無効の判断と、無効確認訴訟の要件を分ける。','処分期間が終われば必ず訴えの利益がないとする。社会的名誉の回復だけを法律上の利益と断定する。','営業停止期間が経過しても、処分歴が法令上の加重処分の要件となるなら、その不利益を取消しで除けるかが問題になる。単なる印象の悪化とは分けて検討する。','取消判決が得られたとして、何を問うと訴えの利益を検討しやすいか。','現在の法的地位がどう改善されるかを問う。','訴えの利益｜出訴期間｜無効｜期間','admin:9,14,36')
L('行政法','admin-04','裁量審査・判断過程・比例原則','裁量の有無と広さは、法律の文言・目的、判断対象の性質から導く。裁量があっても、重要事実の誤認、考慮すべき事項の不考慮、無関係事項の重視、重み付けの著しい不合理があれば違法となり得る。結論の好き嫌いを裁判所の判断で置き換えるだけでは足りない。','根拠条文の要件と効果を分け、どこに判断の余地があるか示す。｜資料の評価、将来予測、利益衡量の各段階を整理する。｜考慮事項の選択と重み付けの誤りを具体的に摘示する。｜目的と負担の均衡、代替手段、過去の取扱いとの整合性を検討する。','裁量があるから適法とする。「社会通念上著しく妥当性を欠く」を引用するだけで事実を評価しない。','施設許可で、現時点の調査だけを見て確実に予定された周辺環境の変化を考慮しなかったなら、その将来事情が根拠法の目的上どれほど重要かを説明して判断過程を検討する。','裁量の有無は何から判断するか。','根拠法令の文言・趣旨・制度構造と、判断の専門性・政策性など対象の性質。','裁量｜考慮｜判断過程｜合理','admin:30')
L('行政法','admin-05','行政手続：申請・不利益処分・理由提示','処分の実体的要件を満たすかと、適正な手続を踏んだかを分ける。申請に対する審査基準、不利益処分の処分基準、聴聞・弁明、理由提示を確認する。条例に基づく地方公共団体の処分等には行政手続法の適用除外があるため、問題文の条例・適用範囲を読む。','申請拒否か、不利益処分か、行政指導かを分類する。｜法律・条例の適用範囲を最初に確認する。｜必要な審査基準・告知・聴聞等と実際の手続を比較する。｜理由提示の程度と、手続違反が処分に及ぼす影響を検討する。','法令名と条文番号だけでなく、具体的な拒否理由が示されているかを見ない。地方公共団体にも全条文を当然適用する。','許可拒否通知が「基準に適合しない」とだけ書く場合、申請者が判断過程を理解して不服申立てできる程度に、どの事実がどの要件に抵触したか示されているかを検討する。','処分が実体的には正しくても、手続の検討は必要か。','必要。手続保障自体の意義と、違反の内容・影響を区別して検討する。','理由提示｜聴聞｜手続｜審査基準','procedure:3,5,8,12,13,14')
L('行政法','admin-06','義務付け・差止め・仮の救済','取消訴訟だけで救済できるかを先に考える。行政庁に処分を求める義務付けには申請型と非申請型があり、要件が異なる。将来の処分を止める差止め、処分の効力等を一時的に止める執行停止、仮の義務付け・差止めも区別する。','現在ある処分か、未処分か、将来の処分かを時系列で示す。｜義務付けは法令に基づく申請の有無から類型を選ぶ。｜重大な損害、補充性、原告適格、併合提起など各類型の要件を確認する。｜本案の違法性と、暫定救済の緊急性・要件を分けて検討する。','取消訴訟を提起しただけで処分の効力が止まるとする。全ての仮の救済に同じ損害要件を用いる。','施設の除却命令を争っても、判決前に建物が取り壊されれば救済が難しい。取消訴訟とともに執行停止の要件を検討し、どの効力・執行を止める必要があるかを示す。','申請型義務付けで、申請を拒否する処分がある場合の訴訟構成は。','拒否処分の取消し又は無効確認等と義務付けを、条文の定める関係で組み合わせる。','義務付け｜差止｜執行停止｜重大な損害','admin:25,37_2,37_3,37_4,37_5')
L('行政法','admin-07','国家賠償1条・2条と規制権限不行使','1条は公権力の行使に当たる公務員の職務行為と故意・過失・違法性等を、2条は公の営造物の設置管理の瑕疵等を扱う。処分が取り消される違法性と国家賠償上の違法性・過失を区別する。規制権限の不行使では権限の趣旨、危険、予見・回避可能性を検討する。','請求する損害と加害行為又は施設を特定する。｜1条・2条のどちらの構成が問題かを示す。｜職務上の注意義務、通常有すべき安全性、危険の程度を事実に即して検討する。｜因果関係と損害、複数主体・過失相殺等を整理する。','処分が違法なら当然に賠償責任があるとする。営造物の事故について公務員の個人的過失を必須とする。','道路の落石事故なら、地形、過去の落石、予防工事、通行止めの可能性、自然条件を踏まえ通常有すべき安全性を検討する。事故が起きた事実だけで瑕疵を認めない。','国家賠償法1条と2条の中心的な対象の違いは。','1条は公務員の公権力行使、2条は公の営造物の設置・管理の瑕疵。','国家賠償｜営造物｜不行使｜安全','state:1,2,3,4')
L('行政法','admin-08','行政法の仕組み解釈と判決の効力','資料の長い個別法を読む際は、目的、権限主体、要件、手続、効果、救済を抽出する。取消判決の形成力・第三者効・拘束力の役割を区別し、判決後に行政庁が何をしなければならないかまで考える。行政指導、行政契約、情報公開なども、法律関係と適切な救済を選ぶ作業から始める。','根拠法の目的規定から保護利益を把握する。｜「できる」「しなければならない」や除外規定を比較する。｜処分・行政指導・契約等の違いに応じた訴訟を選ぶ。｜取消し後の再処分や関連処分への影響を、判決の理由の範囲と結び付ける。','資料中の条文を全て引用する。取消判決後は行政庁が一切別の理由で処分できないとする。','許可拒否の理由が違法として取り消された場合、行政庁は判決の趣旨に従って改めて申請を処理する。新たな拒否理由が許されるかは、判決で否定された判断を繰り返すものかを検討する。','拘束力は、単に処分を消す効果と同じか。','異なる。取消し後の関係行政庁の行動を、判決の趣旨に従わせる効力をいう。','拘束力｜判決｜行政指導｜契約','admin:32,33;procedure:32,33,35')

