assert len({l['id'] for l in lessons})==len(lessons)
OUT.mkdir(parents=True,exist_ok=True)
(OUT/'lessons.json').write_text(json.dumps(lessons,ensure_ascii=False,separators=(',',':'))+'\n')
if len(sys.argv)>1:
 base=pathlib.Path(sys.argv[1]);refs={}
 for l in lessons:
  for law in l['sources']:
   lid=law['lawId'];xml=ET.parse(base/(lid+'.xml')).getroot()
   main=xml.find('.//LawBody/MainProvision')
   for num in law['articles']:
    key=lid+':'+num
    if key in refs:continue
    article=next((a for a in main.iter('Article') if a.get('Num')==num),None) if main is not None else None
    if article is None:raise ValueError(('article not found',l['id'],lid,num))
    pieces=[]
    for para in article.findall('Paragraph'):
     for node in list(para):
      if node.tag in ['ParagraphSentence','Item']:
       pieces.append(re.sub(r'\s+',' ',''.join(node.itertext())).strip())
    refs[key]={'lawId':lid,'name':law['name'],'article':''.join(article.find('ArticleTitle').itertext()),'text':'\n'.join(pieces),'url':law['url']}
 (OUT/'articles.json').write_text(json.dumps({'retrieved':'2026-09-10','note':'e-Gov法令APIから取得した参照用条文。過去問の基準日・施行日を原資料で確認してください。','articles':refs},ensure_ascii=False,separators=(',',':'))+'\n')
print('lessons',len(lessons),'by subject', {s:sum(l['subject']==s for l in lessons) for s in dict.fromkeys(l['subject'] for l in lessons)})
